<section class="panel"><div class="panel-heading"><div><div class="eyebrow"><?= e(t('CURRENT STOCK · တင်း')) ?></div><h2><?= e(t('Rice balances across warehouses')) ?></h2></div><div class="actions"><?php if(can('transfers.create')): ?><a class="button" href="<?= e(url('transfer')) ?>"><?= e(t('⇄ Transfer stock')) ?></a><?php endif; ?><?php if(can('production.create')): ?><a class="button" href="<?= e(url('production')) ?>"><?= e(t('Go to production')) ?></a><?php endif; ?></div></div>
<div class="table-wrap"><table class="inventory-matrix"><thead><tr><th scope="col"><?= e(t('No.')) ?></th><th scope="col"><?= e(t('Rice type')) ?></th><?php foreach($warehouses as $warehouse): ?><th scope="col" class="number"><?= e($warehouse['name']) ?></th><?php endforeach; ?><th scope="col" class="number"><?= e(t('Total')) ?></th></tr></thead><tbody>
<?php foreach($rows as $index=>$r): ?><tr data-rice-id="<?= e($r['id']) ?>"><td><?= $index+1 ?></td><td><strong><?= e($r['rice']) ?></strong></td><?php foreach($warehouses as $warehouse): ?><td class="number"><?= e(num($balances[(int)$r['id']][(int)$warehouse['id']]??0)) ?></td><?php endforeach; ?><td class="number"><strong><?= e(num($r['total'])) ?></strong></td></tr><?php endforeach; ?>
<?php if(!$rows): ?><tr><td colspan="<?= count($warehouses)+3 ?>" class="empty"><?= e(t('No rice types yet. Add rice types to see their warehouse balances.')) ?></td></tr><?php endif; ?></tbody></table></div><div class="panel-foot"><?= e(t('All quantities are in တင်း. Total is the sum across all warehouses.')) ?></div></section>
